import TransportNodeHid from '@ledgerhq/hw-transport-node-hid'
import { SovereignApp } from '@zondax/ledger-sovereign'
import { ed25519 } from '@noble/curves/ed25519'

const PATH = "m/44'/1551'/0'"

const transaction = Buffer.from(
  '0001000b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b1027000000000000000000000000000017171717171717171717171717171717171717171717171717171717171717060000000000000000000000000000000000e876481700000000000000000000000100ca9a3b0000000000ca9a3b00000000e110000000000000',
  'hex',
)
const schema = {
  merkleProof: {
    leavesData: Buffer.from(
      '',
      'hex',
    ),
    leavesIndices: Buffer.from(
      '10000000030000000000000004000000000000000500000000000000080000000000000009000000000000000a000000000000000b0000000000000010000000000000001100000000000000120000000000000020000000000000002100000000000000220000000000000069000000000000006a000000000000006b00000000000000',
      'hex',
    ),
    lemmas: Buffer.from(
      '',
      'hex',
    ),
    treeSize: Buffer.from('6c00000000000000', 'hex'),
    rootHash: Buffer.from('f55d28d6582a2e492b325f097e1ebcc0a19eca8f506fb5a7c3473067d48f06f8', 'hex'),
  },
  chainData: Buffer.from(
    'e1100000000000000900000054657374436861696e060100000009000000746f6b656e5f696473010000002000000017171717171717171717171717171717171717171717171717171717171717060900000054657374546f6b656e',
    'hex',
  ),
  rootTypeIndices: Buffer.from('0400000000000000000000006b0000000000000003000000000000000b00000000000000', 'hex'),
  extraDataHash: Buffer.from('77f986b27d5c6e676fdb865f44833b5fe97f5cccafaf5b4733c21ba027f8b725', 'hex'),
  chainHash: Buffer.from('a43850ba5603f89c05080e14ff868fec09f35fbfaa3c28ad76258fbac95d7432', 'hex'),
}

async function showAddress(app) {
  let resp = await app.deviceInfo()
  console.log('Device Info', resp)
  resp = await app.getVersion()
  console.log('Version', resp)

  resp = await app.getAddressAndPubKey(PATH, true)
  console.log(resp)
  const address = resp.address
  console.log('Address: ' + address.toString('hex'))
}

async function sign(app) {
  try {
    const responseAddr = await app.getAddressAndPubKey(PATH, false)
    const pubKey = responseAddr.pubkey

    const signatureRequest = app.sign(PATH, transaction, schema)
    const signatureResponse = await signatureRequest
    console.log('Signature:', signatureResponse.signature.toString('hex'))

    const chainHash = schema.chainHash
    const txBlobWithChainHash = Buffer.concat([transaction, chainHash])

    const valid = ed25519.verify(signatureResponse.signature, txBlobWithChainHash, pubKey)
    if (valid) {
      console.log('Valid signature')
    } else {
      console.log('Invalid signature')
    }
  } catch (e) {
    console.log(e)
  }
}

async function main() {
  const transport = await TransportNodeHid.default.open()

  const app = new SovereignApp(transport)

  // Enable/disable(uncommenting) to try this features on a real device
  await showAddress(app)
  await sign(app)
}

;(async () => {
  await main()
})()
